package com.hostelcare.controller;
import com.hostelcare.dto.ApiDtos.*;import com.hostelcare.entity.*;import com.hostelcare.enums.*;import com.hostelcare.repository.*;import com.hostelcare.service.ComplaintService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.security.Principal;import java.util.*;import java.time.LocalDate;
@RestController @RequestMapping("/api/admin") public class AdminController {
 private final ComplaintRepository complaints;private final ComplaintService service;private final UserRepository users;private final HostelRepository hostels;private final RoomRepository rooms;private final CategoryRepository categories;private final AssignmentRepository assignments;private final org.springframework.security.crypto.password.PasswordEncoder encoder;
 public AdminController(ComplaintRepository c,ComplaintService s,UserRepository u,HostelRepository h,RoomRepository r,CategoryRepository cat,AssignmentRepository a,org.springframework.security.crypto.password.PasswordEncoder e){complaints=c;service=s;users=u;hostels=h;rooms=r;categories=cat;assignments=a;encoder=e;}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(){return Map.of("total",complaints.count(),"submitted",complaints.countByStatus(ComplaintStatus.SUBMITTED),"assigned",complaints.countByStatus(ComplaintStatus.ASSIGNED),"inProgress",complaints.countByStatus(ComplaintStatus.IN_PROGRESS),"resolved",complaints.countByStatus(ComplaintStatus.RESOLVED),"closed",complaints.countByStatus(ComplaintStatus.CLOSED),"reopened",complaints.countByStatus(ComplaintStatus.REOPENED));}
 @GetMapping("/complaints") public List<?> all(@RequestParam(required=false) String status,@RequestParam(required=false) String priority,@RequestParam(required=false) String category,@RequestParam(required=false) String hostel,@RequestParam(required=false) LocalDate from,@RequestParam(required=false) LocalDate to,@RequestParam(required=false) String q){return complaints.findAllByOrderByCreatedAtDesc().stream().filter(c->status==null||c.status.name().equalsIgnoreCase(status)).filter(c->priority==null||(c.priority!=null&&c.priority.name().equalsIgnoreCase(priority))).filter(c->category==null||c.category.categoryName.equalsIgnoreCase(category)).filter(c->hostel==null||c.room.hostel.hostelName.equalsIgnoreCase(hostel)).filter(c->from==null||!c.createdAt.toLocalDate().isBefore(from)).filter(c->to==null||!c.createdAt.toLocalDate().isAfter(to)).filter(c->q==null||c.title.toLowerCase().contains(q.toLowerCase())||c.student.name.toLowerCase().contains(q.toLowerCase())).map(c->{Map<String,Object> m=ViewMapper.complaint(c);m.put("activeAssignment",assignments.findByComplaintComplaintIdAndActiveTrue(c.complaintId).stream().findFirst().map(a->a.staff.name).orElse("Unassigned"));return m;}).toList();}
 @PutMapping("/complaints/{id}/priority") public Map<String,String> priority(@PathVariable Long id,@Valid @RequestBody PriorityRequest r){service.setPriority(id,r.priority());return Map.of("message","Priority updated.");}
 @PostMapping("/complaints/{id}/assign") public Map<String,String> assign(@PathVariable Long id,@Valid @RequestBody AssignRequest r,Principal p){service.assign(id,r.staffId(),p.getName());return Map.of("message","Staff assigned successfully.");}
 @GetMapping("/students") public List<?> students(){return users.findByRoleAndActiveTrue(Role.STUDENT).stream().map(ViewMapper::user).toList();}
 @GetMapping("/staff") public List<?> staff(){return users.findByRoleAndActiveTrue(Role.STAFF).stream().map(ViewMapper::user).toList();}
 @PostMapping("/staff") public Map<String,Object> createStaff(@Valid @RequestBody CreateStaffRequest r){if(users.existsByEmail(r.email().toLowerCase()))throw new IllegalArgumentException("Email already exists.");User u=new User();u.name=r.name();u.email=r.email().toLowerCase();u.password=encoder.encode(r.password());u.phone=r.phone();u.role=Role.STAFF;users.save(u);return ViewMapper.user(u);}
 @PutMapping("/users/{id}/deactivate") public Map<String,String> deactivate(@PathVariable Long id){User u=users.findById(id).orElseThrow(()->new NoSuchElementException("User not found"));if(u.role==Role.ADMIN)throw new IllegalArgumentException("Admin accounts cannot be deactivated here.");u.active=false;users.save(u);return Map.of("message","User deactivated.");}
 @PostMapping("/hostels") public Map<String,Object> addHostel(@Valid @RequestBody HostelRequest r){Hostel h=new Hostel();h.hostelName=r.hostelName();h.blockName=r.blockName();h.address=r.address();return ViewMapper.hostel(hostels.save(h));}
 @GetMapping("/hostels") public List<?> hostels(){return hostels.findAll().stream().map(ViewMapper::hostel).toList();}
 @PostMapping("/rooms") public Map<String,Object> addRoom(@Valid @RequestBody RoomRequest r){Room room=new Room();room.hostel=hostels.findById(r.hostelId()).orElseThrow(()->new NoSuchElementException("Hostel not found"));room.roomNumber=r.roomNumber();room.floor=r.floor();room.capacity=r.capacity();return ViewMapper.room(rooms.save(room));}
 @GetMapping("/rooms") public List<?> rooms(){return rooms.findAll().stream().map(ViewMapper::room).toList();}
 @PostMapping("/categories") public Map<String,Object> addCategory(@Valid @RequestBody CategoryRequest r){Category c=new Category();c.categoryName=r.categoryName();c.description=r.description();return ViewMapper.category(categories.save(c));}
 @GetMapping("/categories") public List<?> categories(){return categories.findAll().stream().map(ViewMapper::category).toList();}
}
